#!/usr/bin/env python3
# mtimesync.py BASE NEW: give every tracked file in NEW the mtime of the same file in BASE
import os, sys, subprocess
base, new = sys.argv[1], sys.argv[2]
files = subprocess.run(['git', '-C', base, 'ls-files', '-z'], capture_output=True, check=True).stdout.split(b'\0')
n = 0
for f in files:
    if not f: continue
    f = f.decode()
    try:
        st = os.lstat(os.path.join(base, f)); nt = os.lstat(os.path.join(new, f))
    except FileNotFoundError:
        continue
    if st.st_size == nt.st_size and not os.path.islink(os.path.join(new, f)):
        os.utime(os.path.join(new, f), ns=(st.st_atime_ns, st.st_mtime_ns)); n += 1
print(n, 'files synced')
